    <div class="card mt-3"><div class="card-body"><h5 class="mb-3">Breakdown Metode Bayar</h5><?php $totAmt=(float)($summary['total_amount']??0); foreach (($payBreak??[]) as $pb): $amt=(float)($pb['amount']??0); $pct=$totAmt>0?round(($amt/$totAmt)*100):0; ?><div class="mb-2"><div class="d-flex justify-content-between"><div><?= htmlspecialchars($pb['payment_method']??'') ?></div><div>Rp <?= number_format($amt,0,',','.') ?> (<?= $pct ?>%)</div></div><div class="progress"><div class="progress-bar" role="progressbar" style="width: <?= $pct ?>%"></div></div><div class="small text-muted">Transaksi: <?= (int)($pb['tx']??0) ?></div></div><?php endforeach; if (empty($payBreak)): ?><div class="text-muted">Belum ada data</div><?php endif; ?></div></div>
