      <?php foreach ($rows as $x): $code = (string)($x['code'] ?? ''); $cust = (string)($x['customer_name'] ?? ''); $pm = (string)($x['payment_method'] ?? ''); $tot = (float)($x['total'] ?? 0); $crt = (string)($x['created_at'] ?? ''); $sid = (int)($x['id'] ?? 0); $items = ($itemsMap[$sid] ?? []); $ilist = array_map(function($it){ $nm=(string)($it['item_name']??''); $q=(int)($it['qty']??0); $p=(float)($it['price']??0); $sub=$q*$p; return $nm.' x '.$q.' @ Rp '.number_format($p,0,',','.').' = Rp '.number_format($sub,0,',','.'); }, $items); ?>
      <tr><td><?= htmlspecialchars($code) ?></td><td><?= htmlspecialchars($cust) ?></td><td><a href="index.php?r=report/sales&payment_method=<?= urlencode($pm) ?>" class="text-decoration-none"><?= htmlspecialchars($pm) ?></a></td><td>Rp <?= number_format($tot,0,',','.') ?></td><td><?= htmlspecialchars($crt) ?></td><td class="small text-muted"><?= htmlspecialchars(implode('; ', $ilist)) ?></td></tr>
